682	    取自编译选项 MAX_VARIABLE_NUMBER（各 SQLite 版本默认值不同：999、32766、
683	    250000）；取不到时回退到保守的历史默认值 999。
684	    """
685	    try:
686	        for (option,) in database.execute("PRAGMA compile_options"):
687	            if option.startswith(COMPILE_OPTION_PREFIX):
688	                limit = int(option[len(COMPILE_OPTION_PREFIX):])
689	                if limit > 0:
