946	
947	    index = {h: i for i, h in enumerate(headers)}
948	    name_index = index["name"]
949	    date_index = index.get("important_date")
950	
951	    existing = {}
952	    for cid, cname in database.execute("SELECT id, name FROM clients"):
953	        existing[(cname or "").strip().casefold()] = cid
954	
955	    imported = []
956	    failures = []
957	    seen_in_file = {}
958	
959	    for row_number, raw in enumerate(data_rows, start=1):
960	        if len(raw) != len(headers):
961	            failures.append({
962	                "row": row_number,
963	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
964	            })
965	            continue
966	
967	        name = raw[name_index].strip()
968	        problems = []
969	        if not name:
970	            problems.append("缺少名称：name 列为空")
971	        date_value = ""
972	        if date_index is not None:
973	            date_value = raw[date_index].strip()
974	            if date_value:
975	                ok, reason = check_date(date_value)
976	                if not ok:
977	                    problems.append(reason)
978	        if problems:
979	            failures.append({"row": row_number, "reason": "；".join(problems)})
980	            continue
981	
982	        key = name.casefold()
983	        if key in existing:
984	            failures.append({
985	                "row": row_number,
986	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
987	            })
988	            continue
989	        if key in seen_in_file:
990	            failures.append({
991	                "row": row_number,
992	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
993	            })
994	            continue
995	
996	        seen_in_file[key] = row_number
997	        record = {"name": name}
998	        for field_name in OPTIONAL_FIELDS:
999	            idx = index.get(field_name)
1000	            value = raw[idx].strip() if idx is not None else ""
1001	            record[field_name] = value or None
