123	async function openSession(browser, base) {
124	  const page = await browser.newPage();
125	  const modes = {
126	    // ok 正常转发；close 连接断开；500 非成功状态；bad-json 无法解析；
127	    // no-clients 可解析但缺少客户数组
128	    list: "ok",
129	    // batch 响应改写：null = 走真实后端；否则用给定 {status, body}
130	    batchOverride: null,
131	    // batchHold 为 true 时挂起保存请求（既不应答也不转发），模拟服务尚未给出结果
132	    batchHold: false,
133	    // batchAbort 为 true 时直接断开保存请求连接（收不到任何响应）
134	    batchAbort: false,
135	  };
136	  const counts = {batchPosts: 0, listGets: 0};
137	  // 被挂起的保存请求：{request, payload}，放行时 continue 发往真实后端
138	  const held = [];
139	
140	  await page.setRequestInterception(true);
141	  page.on("request", request => {
142	    const url = request.url();
143	    if (request.method() === "GET" && url.endsWith("/api/clients")) {
144	      counts.listGets += 1;
145	      if (modes.list === "close") { request.abort("failed"); return; }
146	      if (modes.list === "500") {
147	        request.respond({status: 500, contentType: "application/json; charset=utf-8",
148	          body: JSON.stringify({error: "模拟的服务错误"})});
149	        return;
150	      }
151	      if (modes.list === "bad-json") {
152	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
153	          body: "<<<not valid json>>>"});
154	        return;
155	      }
156	      if (modes.list === "no-clients") {
157	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
158	          body: JSON.stringify({unexpected: true})});
159	        return;
160	      }
161	      request.continue();
162	      return;
163	    }
164	    if (request.method() === "POST" && url.endsWith("/api/clients/batch-update")) {
165	      counts.batchPosts += 1;
166	      if (modes.batchHold) {
167	        held.push({request, payload: request.postData()});
168	        return;
169	      }
170	      if (modes.batchAbort) {
171	        request.abort("failed");
172	        return;
173	      }
174	      if (modes.batchOverride) {
175	        const {status, body, ct} = modes.batchOverride;
176	        request.respond({status,
177	          contentType: ct || "application/json; charset=utf-8", body});
178	        return;
179	      }
180	    }
181	    request.continue();
182	  });
183	
184	  await page.setCacheEnabled(false);
185	  await page.goto(base + "/", {waitUntil: "networkidle0"});
186	  return {page, modes, counts, held};
187	}
