1	#!/usr/bin/env node
2	/**
3	 * 首页 CSV 导入结果展示的页面层面回归保障。
4	 *
5	 * 启动真实 app.py 服务（与 smoke_test.py / page_test.mjs 同一后端，不模拟、
6	 * 不改动接口公开行为与现有导入规则），用 Puppeteer 驱动系统 Chrome 打开首页，
7	 * 用真实文件选择框上传 CSV；对「服务返回内容」和「导入后的客户列表读取」分别
8	 * 做请求拦截，逐项验证页面严格区分「拿到完整可靠的导入报告」与「只收到成功
9	 * 状态、结果无法确认」：
10	 *
11	 * A. 完整有效报告：显示报告里的新增/未导入数量，按原文件数据记录编号逐条展示
12	 *    原因（表头不计编号，引号字段内换行不拆记录）；覆盖有效/无效混在同一文件
13	 *    的部分成功、仅表头的合法零新增、全部因重复或字段问题跳过（不得说成整份
14	 *    文件被拒绝）；
15	 * B. 成功状态但回复无法解析、数量不是非负整数（负数/小数/文本/布尔/缺失）、
16	 *    未导入明细缺失或条数不符、明细编号不是正整数或原因不是非空文本：一律
17	 *    显示结果无法确认，提示先核对客户列表再决定是否重新导入；不显示成功数量，
18	 *    不补造零新增/空明细，页面不出现 undefined/NaN；页面也不能凭客户列表的
19	 *    行数推算新增数量；
20	 * C. 已取得有效报告后，随后的客户列表读取失败（连接失败 / 500 / 无法解析 /
21	 *    缺少 clients 数组）不改变已确认的数量与逐条原因：附加列表暂未更新、
22	 *    资料可能不是最新、稍后刷新即可、无需重新导入的提示；旧客户行保留，不被
23	 *    清空、不显示空列表提示；重新打开读取成功后显示实际保存的资料；
24	 * D. 结果处理结束后导入按钮恢复可用、已选文件保留、不会自动再次提交；
25	 * E. 正常导入并成功刷新列表的路径，以及整份文件被明确拒绝（HTTP 400）时
26	 *    原有错误说明与资料不变的行为继续保留；网络失败与其他非成功状态同样按
27	 *    「无法确认」处理。
28	 * H. HTTP 400 只在有明确可读原因（对象非空文本 error / 非空纯文本，去首尾
29	 *    空白，特殊字符按文字展示）时才提示整份文件拒绝、本次零新增、资料保持
30	 *    原样；空回复、仅含空白、回复体读取失败、可解析为 JSON 但无合格 error
31	 *    （{"message":...}、null、字符串形式 JSON 等）、error 为空白或非文本，
32	 *    一律保留 HTTP 400 按无法确认处理：不展示原始 JSON、不显示数量、不声称
33	 *    回滚或整份拒绝，文件与旧表保留、不刷新列表、不自动重发。缺少 name
34	 *    表头、UTF-8 编码错误、引号结构损坏等真实文件级错误仍走明确拒绝。
35	 * I. 提交后到拿到回复期间：按钮显示「正在导入…」且不可点击，页面只有等待
36	 *    提示、原有客户仍可见；重复提交（重复触发 submit、requestSubmit 等回车
37	 *    同样会走的表单提交路径）不增加导入请求，也不把等待提示换成成功或
38	 *    「请先选择 CSV 文件」。等待期间可以另选文件或取消选择，文件名按当前
39	 *    选择显示，但按钮继续等待；放行后落库结果、报告数量与逐条原因只属于
40	 *    第一次提交的文件，后来选中的文件不会自动导入。处理结束后按钮恢复
41	 *    「导入」并可用，文件选择保留为结果处理结束时的状态（后来另选的文件
42	 *    或取消后的未选状态），不恢复提交时的旧选择；之后用户主动提交才使用
43	 *    当时选中的文件。
44	 * J. 等待期间另选了合法文件，而最初提交的文件缺少 name 表头被真实后端以
45	 *    HTTP 400 明确拒绝：展示拒绝原因、不显示成功数量、原客户资料不变；
46	 *    等待期间后来选择的合法文件仍保留，按钮恢复后由用户主动提交才导入。
47	 * K. 等待期间取消文件选择：结束后文件保持未选状态，此时直接提交只提示
48	 *    「请先选择 CSV 文件」且不发送请求；重新选择合法文件后能够正常提交，
49	 *    证明上一次等待没有留下不可提交状态。
50	 * L. 成功报告已经显示、但导入后的客户列表仍在读取（挂起）期间：按钮继续
51	 *    不可提交，重复提交不增加请求；列表读取失败时已确认的报告与逐条原因、
52	 *    此前显示的客户保留，附加列表暂未更新、稍后刷新即可、无需重新导入的
53	 *    提示，处理结束后解除等待。
54	 */
55	import {spawn} from "node:child_process";
56	import {dirname, join} from "node:path";
57	import {fileURLToPath} from "node:url";
58	import {mkdtempSync, mkdirSync, rmSync, writeFileSync, readFileSync} from "node:fs";
59	import {tmpdir} from "node:os";
60	import puppeteer from "puppeteer";
61	
62	const HERE = dirname(fileURLToPath(import.meta.url));
63	const APP = join(HERE, "app.py");
64	const TMP = mkdtempSync(join(tmpdir(), "clientbook-import-page-"));
65	const FAILURES = [];
66	let checkCount = 0;
67	
68	function check(label, cond, detail = "") {
69	  checkCount += 1;
70	  if (cond) {
71	    console.log("PASS", label);
72	  } else {
73	    FAILURES.push({label, detail: typeof detail === "string" ? detail : JSON.stringify(detail)});
74	    console.log("FAIL", label, typeof detail === "string" ? detail : JSON.stringify(detail));
75	  }
76	}
77	
78	const norm = s => (s || "").replace(/[ \t\r\n]+/g, " ").trim();
79	
80	// ---------------------------------------------------------------------------
81	// 真实 app.py 进程
82	// ---------------------------------------------------------------------------
83	function startApp(label) {
84	  const proc = spawn("python3", [
85	    APP, "serve", "--host", "127.0.0.1", "--port", "0",
86	    "--data-dir", join(TMP, label),
87	  ], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
88	  const port = new Promise((resolve, reject) => {
89	    let buf = "";
90	    const onData = d => {
91	      buf += d.toString();
92	      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
93	      if (m) {
94	        proc.stdout.off("data", onData);
95	        resolve(Number(m[1]));
96	      }
97	    };
98	    proc.stdout.on("data", onData);
99	    proc.on("exit", code => reject(new Error(`app.py 意外退出（${code}）：${buf}`)));
100	  });
101	  return {proc, port};
102	}
103	
104	async function waitReady(base, deadlineMs = 8000) {
105	  const deadline = Date.now() + deadlineMs;
106	  while (Date.now() < deadline) {
107	    try {
108	      const res = await fetch(base + "/health");
109	      if (res.status === 200) return;
110	    } catch { /* 尚未就绪 */ }
111	    await new Promise(r => setTimeout(r, 100));
112	  }
113	  throw new Error("服务未在限定时间内就绪：" + base);
114	}
115	
116	async function stopApp(ctx) {
117	  ctx.proc.kill(); // SIGTERM：app.py 收到后走正常关闭
118	  const timer = setTimeout(() => {
119	    try { ctx.proc.kill("SIGKILL"); } catch { /* 已退出 */ }
120	  }, 2000);
121	  await new Promise(r => ctx.proc.on("exit", r));
122	  clearTimeout(timer);
123	}
124	
125	async function startServer(label) {
126	  const {proc, port: portPromise} = startApp(label);
127	  const base = `http://127.0.0.1:${await portPromise}`;
128	  await waitReady(base);
129	  return {proc, base};
130	}
131	
132	// ---------------------------------------------------------------------------
133	// CSV 构造与后端直连准备数据
134	// ---------------------------------------------------------------------------
135	const csvField = v => `"${String(v).replace(/"/g, '""')}"`;
136	const buildCsv = (header, rows) =>
137	  header.map(csvField).join(",") + "\n" +
138	  rows.map(r => r.map(csvField).join(",")).join("\n") + "\n";
139	
140	async function importCsvDirect(base, csv) {
141	  const res = await fetch(base + "/api/clients/import", {method: "POST", body: csv});
142	  const data = await res.json();
143	  if (res.status !== 200) throw new Error("seed 失败：" + JSON.stringify(data));
144	  return data;
145	}
146	
147	async function seed(base, names) {
148	  const csv = buildCsv(["name"], names.map(n => [n]));
149	  const data = await importCsvDirect(base, csv);
150	  return new Map(data.imported.map(x => [x.name, x.id]));
151	}
152	
153	async function listClients(base) {
154	  const res = await fetch(base + "/api/clients");
155	  return res.json();
156	}
157	
158	// ---------------------------------------------------------------------------
159	// 页面驱动：拦截导入请求与导入后的客户列表读取
160	// ---------------------------------------------------------------------------
161	async function openSession(browser, base, options = {}) {
162	  const page = await browser.newPage();
163	  const modes = {
164	    // ok 正常转发；close 连接断开；500 非成功状态；bad-json 无法解析；
165	    // no-clients 可解析但缺少客户数组
166	    list: "ok",
167	    // listHold 为 true 时挂起客户列表读取（既不应答也不转发），
168	    // 模拟「导入成功报告已显示、但列表仍在读取」的阶段
169	    listHold: false,
170	    // importOverride：null = 走真实后端；否则用给定 {status, body, contentType}
171	    importOverride: null,
172	    // importHold 为 true 时挂起导入请求（既不应答也不转发），模拟服务尚未给出结果
173	    importHold: false,
174	    // importAbort 为 true 时直接断开导入请求（模拟网络错误）
175	    importAbort: false,
176	  };
177	  const counts = {importPosts: 0, listGets: 0};
178	  // 被挂起的请求：放行时 continue 发往真实后端（文件上传请求体在拦截层
179	  // 不可读，内容归属用放行后的真实落库结果来验证）
180	  const heldImports = [];
181	  const heldLists = [];
182	
183	  // options.importReadFailStatus：让导入请求拿到该状态码，但回复体由一个
184	  // 在读取时即失败的 ReadableStream 承载——res.status 可读而 res.text()
185	  // 拒绝，模拟「连接在投递响应体过程中断开」。请求不离开页面，后端收不到。
186	  if (options.importReadFailStatus) {
187	    await page.evaluateOnNewDocument((status) => {
188	      const origFetch = window.fetch.bind(window);
189	      window.fetch = (input, init) => {
190	        const url = input && input.url ? input.url : String(input);
191	        if (url.includes("/api/clients/import")) {
192	          const stream = new ReadableStream({
193	            start(controller) {
194	              controller.error(new TypeError("unexpected end of stream"));
195	            },
196	          });
197	          return Promise.resolve(new Response(stream, {
198	            status,
199	            headers: {"Content-Type": "application/json; charset=utf-8"},
200	          }));
201	        }
202	        return origFetch(input, init);
203	      };
204	    }, options.importReadFailStatus);
205	  }
206	
207	  await page.setRequestInterception(true);
208	  page.on("request", request => {
209	    const url = request.url();
210	    if (request.method() === "GET" && url.endsWith("/api/clients")) {
211	      counts.listGets += 1;
212	      if (modes.listHold) {
213	        heldLists.push(request);
214	        return;
215	      }
216	      if (modes.list === "close") { request.abort("failed"); return; }
217	      if (modes.list === "500") {
218	        request.respond({status: 500, contentType: "application/json; charset=utf-8",
219	          body: JSON.stringify({error: "模拟的服务错误"})});
220	        return;
221	      }
222	      if (modes.list === "bad-json") {
223	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
224	          body: "<<<not valid json>>>"});
225	        return;
226	      }
227	      if (modes.list === "no-clients") {
228	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
229	          body: JSON.stringify({unexpected: true})});
230	        return;
231	      }
232	      request.continue();
233	      return;
234	    }
235	    if (request.method() === "POST" && url.endsWith("/api/clients/import")) {
236	      counts.importPosts += 1;
237	      if (modes.importHold) {
238	        heldImports.push(request);
239	        return;
240	      }
241	      if (modes.importAbort) { request.abort("failed"); return; }
242	      if (modes.importOverride) {
243	        const {status, body, contentType} = modes.importOverride;
244	        request.respond({
245	          status,
246	          contentType: contentType || "application/json; charset=utf-8",
247	          body,
248	        });
249	        return;
250	      }
251	    }
252	    request.continue();
253	  });
254	
255	  await page.setCacheEnabled(false);
256	  await page.goto(base + "/", {waitUntil: "networkidle0"});
257	  return {page, modes, counts, heldImports, heldLists};
258	}
259	
260	// 读取导入区域与客户列表的全部可见状态
261	async function importSnap(page) {
262	  return page.evaluate(() => {
263	    const text = sel => document.querySelector(sel)?.textContent.trim() ?? null;
264	    const report = document.getElementById("report");
265	    return {
266	      reportVisible: report.style.display === "block",
267	      banners: [...report.querySelectorAll(".banner")].map(b => ({
268	        cls: b.className,
269	        text: b.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
270	      })),
271	      reportText: report.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
272	      failureItems: [...report.querySelectorAll(".failures li")]
273	        .map(li => li.innerText.replace(/[ \t\r\n]+/g, " ").trim()),
274	      failuresTitle: (() => {
275	        const p = report.querySelector(".failures p");
276	        return p ? p.innerText.replace(/[ \t\r\n]+/g, " ").trim() : null;
277	      })(),
278	      filename: text("#filename"),
279	      submitText: text("#submit-btn"),
280	      submitDisabled: document.getElementById("submit-btn").disabled,
281	      fileCount: document.getElementById("file-input").files.length,
282	      rows: [...document.querySelectorAll("#clients-body tr")].map(tr => ({
283	        id: tr.dataset.id,
284	        // td: 0 勾选框, 1 编号, 2 名称, 3 来源, 4 地区, 5 行业, 6 重要日期
285	        cells: [...tr.querySelectorAll("td")].slice(2).map(td => td.textContent.trim()),
286	      })),
287	      emptyOn: document.getElementById("clients-empty").classList.contains("on"),
288	      tableDisplay: getComputedStyle(document.getElementById("clients-table")).display,
289	      loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
290	      loadErrorText: text("#clients-load-error"),
291	    };
292	  });
293	}
294	
295	async function uploadCsv(page, name, content) {
296	  // 此版本 Puppeteer 的 uploadFile 只接受本地路径：写到临时目录再通过真实文件选择框上传
297	  const dir = join(TMP, "uploads");
298	  mkdirSync(dir, {recursive: true});
299	  const path = join(dir, name);
300	  writeFileSync(path, content, "utf8");
301	  const input = await page.$("#file-input");
302	  await input.uploadFile(path);
303	  await page.waitForFunction(name => document.getElementById("filename").textContent === name,
304	    {}, name);
305	}
306	
307	async function submitImport(session) {
308	  const {page, counts} = session;
309	  const before = counts.importPosts;
310	  await page.click("#submit-btn");
311	  await page.waitForSelector("#report .banner", {timeout: 5000});
312	  // 结果处理结束后导入按钮必须恢复可用
313	  await page.waitForFunction(() => !document.getElementById("submit-btn").disabled,
314	    {timeout: 5000});
315	  await new Promise(r => setTimeout(r, 80)); // 让横幅/列表渲染稳定
316	  return before;
317	}
318	
319	// 只触发提交并进入等待（不等待结果）：用于挂起请求的场景
320	async function startImport(session) {
321	  const {page} = session;
322	  await page.click("#submit-btn");
323	  await page.waitForSelector("#report .banner.busy", {timeout: 5000});
324	  await page.waitForFunction(
325	    () => document.getElementById("submit-btn").textContent === "正在导入…",
326	    {timeout: 3000});
327	}
328	
329	async function waitForHeld(list, timeout = 5000) {
330	  const deadline = Date.now() + timeout;
331	  while (Date.now() < deadline) {
332	    if (list.length > 0) return list[0];
333	    await new Promise(r => setTimeout(r, 25));
334	  }
335	  throw new Error("挂起的请求未在限定时间内出现");
336	}
337	
338	// 等待导入结果处理全部结束（按钮恢复「导入」并可用），再留一点渲染稳定时间
339	async function waitImportDone(page) {
340	  await page.waitForFunction(
341	    () => !document.getElementById("submit-btn").disabled &&
342	      document.getElementById("submit-btn").textContent === "导入",
343	    {timeout: 8000});
344	  await new Promise(r => setTimeout(r, 80));
345	}
346	
347	// 等待期间再次触发表单提交：重复触发 submit 事件与 requestSubmit()——
348	// 按钮获得焦点按回车时浏览器走的就是 requestSubmit 表单提交路径。
349	// 若存在多个 submit 按钮时 requestSubmit 以触发性按钮为准，这里页面只有一个。
350	async function tryResubmit(page) {
351	  await page.evaluate(() => {
352	    const form = document.getElementById("import-form");
353	    form.dispatchEvent(new Event("submit", {cancelable: true, bubbles: true}));
354	    form.requestSubmit();
355	  });
356	  await new Promise(r => setTimeout(r, 150)); // 给潜在的错误请求留出发出时间
357	}
358	
359	// 取消文件选择：点击真实文件选择框上的「取消」在无头环境无法稳定触发，
360	// 这里直接清空 FileList 并派发 change（与用户取消后控件回到未选状态等效，
361	// change 监听与按钮等待保护对此完全一致）。
362	async function clearFile(page) {
363	  await page.evaluate(() => {
364	    const input = document.getElementById("file-input");
365	    const dt = new DataTransfer();
366	    input.files = dt.files;
367	    input.dispatchEvent(new Event("change", {bubbles: true}));
368	  });
369	  await page.waitForFunction(() =>
370	    document.getElementById("file-input").files.length === 0 &&
371	    document.getElementById("filename").textContent === "");
372	}
373	
374	// ---- 报告口径断言 ----------------------------------------------------------
375	
376	// 成功报告横幅：「新增 X 条，未导入 Y 条。」
377	function successBanner(snap, imported, failed) {
378	  return snap.banners.some(b => b.cls.includes("ok") &&
379	    new RegExp(`新增\\s*${imported}\\s*条，未导入\\s*${failed}\\s*条`).test(b.text));
380	}
381	
382	// 「结果无法确认」横幅的共同口径
383	function expectUnconfirmed(snap, ctx) {
384	  check(`${ctx}：只有一条错误横幅、无成功/警告横幅`,
385	    snap.banners.length === 1 && snap.banners[0].cls.includes("bad") &&
386	    !snap.banners.some(b => b.cls.includes("ok") || b.cls.includes("warn")),
387	    snap.banners);
388	  check(`${ctx}：提示结果无法确认、先核对客户列表、再决定是否重新导入`,
389	    /无法确认/.test(snap.reportText) &&
390	    snap.reportText.includes("核对客户列表") &&
391	    snap.reportText.includes("重新导入"),
392	    snap.reportText);
393	  check(`${ctx}：不显示任何成功数量（不补造零新增/空明细）`,
394	    !/新增\s*\d+\s*条/.test(snap.reportText) &&
395	    !/未导入\s*\d+\s*条/.test(snap.reportText),
396	    snap.reportText);
397	  check(`${ctx}：不渲染未导入明细、页面没有 undefined/NaN/[object Object]`,
398	    snap.failureItems.length === 0 && !snap.failuresTitle &&
399	    !/undefined|NaN|\[object Object\]/.test(snap.reportText),
400	    {items: snap.failureItems, text: snap.reportText});

