  const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1",
    "--port", "0", "--data-dir", join(TMP, label)],
    {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
  const port = new Promise((resolve, reject) => {
    let buf = "";
    const onData = d => { buf += d.toString(); const m = buf.match(/:(\d+)/); if (m) { proc.stdout.off("data", onData); resolve(Number(m[1])); } };
    proc.stdout.on("data", onData);
    proc.on("exit", c => reject(new Error("exit " + c + buf)));
  });
  return {proc, port};
}
