const HERE = dirname(fileURLToPath(import.meta.url));
const TMP = mkdtempSync(join(tmpdir(), "stale-verify-"));
let failures = 0;
function check(label, cond, detail) {
  if (cond) console.log("PASS", label);
  else { failures++; console.log("FAIL", label, detail ?? ""); }
}

function startApp(label) {
  const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1",
    "--port", "0", "--data-dir", join(TMP, label)],
    {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
  const port = new Promise((resolve, reject) => {
    let buf = "";
    const onData = d => { buf += d.toString(); const m = buf.match(/:(\d+)/); if (m) { proc.stdout.off("data", onData); resolve(Number(m[1])); } };
    proc.stdout.on("data", onData);
    proc.on("exit", c => reject(new Error("exit " + c + buf)));
  });
  return {proc, port};
}
async function ready(base) { for (;;) { try { if ((await fetch(base + "/health")).status === 200) return; } catch {} await new Promise(r => setTimeout(r, 100)); } }
async function stop(p) { p.kill(); await new Promise(r => p.on("exit", r)); }

const csvField = v => `"${String(v).replace(/"/g, '""')}"`;
const buildCsv = (h, rows) => h.map(csvField).join(",") + "\n" + rows.map(r => r.map(csvField).join(",")).join("\n") + "\n";

async function open(browser, base, {holdAll}) {
  const page = await browser.newPage();
  const held = [];
  let hold = !!holdAll;
  await page.setRequestInterception(true);
  page.on("request", req => {
    const u = req.url();
    if (req.method() === "GET" && u.endsWith("/api/clients")) {
      if (hold) { held.push(req); return; }
      req.continue(); return;
    }
    req.continue();
  });
  await page.setCacheEnabled(false);
  await page.goto(base + "/", {waitUntil: holdAll ? "domcontentloaded" : "networkidle0"});
  return {page, held, setHold: v => { hold = v; }};
}

async function snap(page) {
  return page.evaluate(() => ({
    rows: [...document.querySelectorAll("#clients-body tr")].map(tr =>
      tr.cells[2].textContent.trim()),
    emptyOn: document.getElementById("clients-empty").classList.contains("on"),
    errOn: document.getElementById("clients-load-error").classList.contains("on"),
    errText: document.getElementById("clients-load-error").textContent.trim(),
    selCount: document.getElementById("sel-count").textContent.trim(),
    chips: [...document.querySelectorAll(".sel-chip")].map(c => c.textContent.replace(/\s*×$/, "").trim()),
    report: document.getElementById("report").innerText.replace(/[ \t\r\n]+/g, " ").trim(),
  }));
}
async function upload(page, name, content) {
  const dir = join(TMP, "up"); mkdirSync(dir, {recursive: true});
  const p = join(dir, name); writeFileSync(p, content, "utf8");
  await (await page.$("#file-input")).uploadFile(p);
  await page.waitForFunction(n => document.getElementById("filename").textContent === n, {}, name);
}
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitHeldN(held, n, timeout = 5000) {
  const d = Date.now() + timeout;
  while (Date.now() < d) { if (held.length >= n) return; await sleep(25); }
  throw new Error("held 数量未达到 " + n + "（实际 " + held.length + "）");
}

const browser = await puppeteer.launch({executablePath: process.env.CHROME || "/usr/bin/google-chrome",
  headless: true, args: ["--no-sandbox", "--disable-dev-shm-usage"]});

// ============ 场景 1：首次读取（旧）挂起，导入成功触发的新读取先返回；
//              旧读取随后返回「空列表」/各种失败 —— 页面必须保持新客户。 ============
for (const [label, resolveOld] of [
  ["空列表", req => req.respond({status: 200, contentType: "application/json", body: JSON.stringify({clients: []})})],
  ["连接错误", req => req.abort("failed")],
  ["HTTP 500", req => req.respond({status: 500, contentType: "application/json", body: JSON.stringify({error: "x"})})],
  ["无法解析", req => req.respond({status: 200, contentType: "application/json", body: "garbage"})],
  ["缺少数组", req => req.respond({status: 200, contentType: "application/json", body: JSON.stringify({})})],
]) {
  const {proc, port: pp} = startApp("s1-" + label);
  const base = `http://127.0.0.1:${await pp}`;
  await ready(base);
  const s = await open(browser, base, {holdAll: true});
  const {page, held} = s;
  await sleep(100);
  check(`1[${label}] 首次读取已发起并被挂起`, held.length === 1, String(held.length));

  await upload(page, "f.csv", buildCsv(["name"], [["导入新客户"]]));
  await page.click("#submit-btn");
  await page.waitForFunction(() => held.length >= 2, {timeout: 5000});
  // 新读取（import 触发）放行 → 真实后端返回导入后的 1 名客户
  held[1].continue();
  await page.waitForFunction(() => !document.getElementById("submit-btn").disabled, {timeout: 5000});
  await sleep(80);
  let st = await snap(page);
  check(`1[${label}] 新读取先应用：显示新增客户、无空列表/失败提示`,
    st.rows.length === 1 && st.rows[0] === "导入新客户" && !st.emptyOn && !st.errOn,
    JSON.stringify(st));

  // 旧读取（首次）随后才回复 —— 无论空列表还是失败都必须被忽略
  resolveOld(held[0]);
  await sleep(200);
  st = await snap(page);
  check(`1[${label}] 旧回复被忽略：仍显示新客户`, st.rows.length === 1 && st.rows[0] === "导入新客户", JSON.stringify(st.rows));
  check(`1[${label}] 旧回复被忽略：不出现“还没有客户记录”`, !st.emptyOn, "emptyOn");
  check(`1[${label}] 旧回复被忽略：不新增读取失败提示`, !st.errOn, st.errText);
  check(`1[${label}] 已确认导入报告不受影响：新增 1 条`, /新增\s*1\s*条/.test(st.report), st.report);
  await page.close();
  await stop(proc);
}

// ============ 场景 2：最近发起的读取失败 → 提示暂未更新、保留已显示行；
//              较早读取之后才成功也不能撤提示或换表。 ============
{
  const {proc, port: pp} = startApp("s2");
  const base = `http://127.0.0.1:${await pp}`;
  await ready(base);
  // 先正常落两名客户并让首屏渲染
  await fetch(base + "/api/clients/import", {method: "POST", body: buildCsv(["name"], [["甲"], ["乙"]])});
  const s = await open(browser, base, {holdAll: false});
  const {page} = s;
  await page.waitForFunction(() => document.querySelectorAll("#clients-body tr").length === 2);
  // 勾选甲
  await page.evaluate(() => document.querySelector('#clients-body tr[data-id="1"] .row-check').click());
  let st0 = await snap(page);
  check("2 准备：显示两行、已勾选甲", st0.rows.length === 2 && st0.selCount === "1" && st0.chips[0].includes("甲"), JSON.stringify(st0.chips));

  // 连续发起两次读取：较早 p1、最新 p2；都先挂起
  s.setHold(true);
  const settled = page.evaluate(() => {
    window.__p1 = loadClients().catch(e => "p1:" + e.message);
    window.__p2 = loadClients().catch(e => "p2:" + e.message);
    return true;
  });
  await settled;
  await page.waitForFunction(() => true); // noop
  await sleep(100);
  check("2 两次读取均已发起并挂起", s.held.length === 2, String(s.held.length));

  // 最新 p2 先失败
  s.held[1].abort("failed");
  await page.evaluate(() => window.__p2);
  await sleep(150);
  let st = await snap(page);
  check("2 最新读取失败：显示读取失败/暂未最新提示，保留两行",
    st.errOn && st.rows.length === 2 && !st.emptyOn, JSON.stringify({err: st.errOn, rows: st.rows.length, empty: st.emptyOn}));
  check("2 最新读取失败：勾选与已选客户说明保留", st.selCount === "1" && st.chips[0].includes("甲"), JSON.stringify(st.chips));

  // 较早 p1 随后成功，但返回的是缺少甲的旧列表——必须整份忽略
  s.held[0].respond({status: 200, contentType: "application/json",
    body: JSON.stringify({clients: [{id: 2, name: "乙"}]})});
  await sleep(200);
  st = await snap(page);
  check("2 较早成功不能撤掉失败提示", st.errOn, "errOn removed");
  check("2 较早成功不能换掉保留的表格（仍是两行）", st.rows.length === 2 && st.rows.includes("甲") && st.rows.includes("乙"), JSON.stringify(st.rows));
  check("2 较早成功不能因旧列表缺号清除勾选/已选说明",
    st.selCount === "1" && st.chips.length === 1 && st.chips[0].includes("甲"), JSON.stringify(st.chips));
  await page.close();
  await stop(proc);
}

// ============ 场景 3：较新读取仍在等待，较早回复（缺号）不能抢先清勾选。 ============
{
  const {proc, port: pp} = startApp("s3");
  const base = `http://127.0.0.1:${await pp}`;
  await ready(base);
  await fetch(base + "/api/clients/import", {method: "POST", body: buildCsv(["name"], [["子"], ["丑"]])});
  const s = await open(browser, base, {holdAll: false});
  const {page} = s;
  await page.waitForFunction(() => document.querySelectorAll("#clients-body tr").length === 2);
  await page.evaluate(() => document.querySelector('#clients-body tr[data-id="1"] .row-check').click());

  s.setHold(true);
  await page.evaluate(() => { window.__a = loadClients().catch(() => {}); window.__b = loadClients().catch(() => {}); });
  await sleep(100);
  // 较早读取先回复：旧列表缺少编号 1
  s.held[0].respond({status: 200, contentType: "application/json",
    body: JSON.stringify({clients: [{id: 2, name: "丑"}]})});
  await sleep(200);
  let st = await snap(page);
  check("3 较新读取等待中：较早回复不抢先决定内容（仍两行）", st.rows.length === 2, JSON.stringify(st.rows));
  check("3 较早回复不能清除勾选与已选说明", st.selCount === "1" && st.chips[0].includes("子"), JSON.stringify(st.chips));
  check("3 较早回复不产生空列表/失败提示", !st.emptyOn && !st.errOn, "");

  // 最新读取成功返回真实两行
  s.held[1].continue();
  await sleep(200);
  st = await snap(page);
  check("3 最新读取成功：显示真实两行、无失败提示、勾选保留",
    st.rows.length === 2 && !st.errOn && st.selCount === "1" && st.chips[0].includes("子"),
    JSON.stringify(st));
  await page.close();
  await stop(proc);
}

await browser.close();
rmSync(TMP, {recursive: true, force: true});
console.log(failures ? `\n${failures} 项失败` : "\n临时验证全部通过");
process.exit(failures ? 1 : 0);

